def is_sorted(lst):
    previous = -1
    repeated = 0
    result = True
    value = 0
    for value in lst:
        if value < previous:
            result = False
        if value == previous:
            repeated += 1
        else:
            repeated = 1
        if repeated > 2:
            result = False
        previous = value
    return result

